{
  "narrative_summary": "This result rests on the link from Engineering Capacity to Total Cost of Ownership. If capacity assumptions shift, more runs could support a different option. In this model, 58% of runs supported Rebuild In House.",
  "story_headlines": {
    "opt_rebuild": "Rebuild In House depends on engineering capacity holding up as modelled, which is not yet evidence backed.",
    "opt_extend": "Extend Vendor Contract would gain more support if vendor price path proves steadier than modelled capacity."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 61% of variations, based on current estimates given the low confidence behind it.",
    "primary_risk": "The link from Engineering Capacity to Total Cost of Ownership is the single biggest threat to this result.",
    "stability_factors": [
      "Vendor Price Path has comparatively firmer confidence behind its influence on Total Cost of Ownership."
    ],
    "fragility_factors": [
      "The link from Engineering Capacity to Total Cost of Ownership could flip which option more runs support."
    ]
  },
  "readiness_rationale": "Two gaps still hold this back: Engineering Capacity is asserted rather than evidenced, and overall confidence in the comparison is low.",
  "evidence_enhancements": {
    "fac_eng_capacity": {
      "specific_action": "Run a capacity audit against current engineering headcount and planned commitments before committing to a rebuild timeline.",
      "rationale": "This factor carries the highest value evidence you could gather and currently rests on an unsupported assertion.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the capacity answer before looking at the audit data."
    },
    "fac_vendor_price": {
      "specific_action": "Request the vendor's forward pricing schedule or escalation clauses in writing.",
      "rationale": "Vendor Price Path still carries meaningful value of information despite firmer confidence than capacity.",
      "evidence_type": "market_research",
      "decision_hygiene": "Write down your expected price path before reading the vendor's terms."
    }
  },
  "scenario_contexts": {
    "edge_capacity_tco": {
      "trigger_description": "If Engineering Capacity falls short of what Total Cost of Ownership assumptions require...",
      "consequence": "...then the most runs would support Extend Vendor Contract rather than Rebuild In House."
    }
  },
  "flip_thresholds": [],
  "bias_findings": [
    {
      "type": "DOMINANT_FACTOR",
      "source": "structural",
      "description": "Engineering Capacity is asserted rather than evidenced, yet it anchors the comparison between these options. Is that assertion solid enough to act on?",
      "affected_elements": [
        "fac_eng_capacity",
        "edge_capacity_tco"
      ],
      "suggested_action": "Validate the capacity assumption with a staffing review before treating this comparison as settled.",
      "linked_critique_code": "unsupported_link"
    }
  ],
  "key_assumptions": [
    "The link from Engineering Capacity to Total Cost of Ownership assumes current staffing levels and commitments are accurately understood.",
    "The link from Vendor Price Path to Total Cost of Ownership assumes the vendor's pricing behaviour continues on its current path.",
    "The brief frames this as a build versus extend choice, assuming no third option such as a partial migration is viable."
  ],
  "decision_quality_prompts": [
    {
      "question": "What is the base rate for in house platform rebuilds completing on their original engineering capacity estimate?",
      "principle": "Outside View (Kahneman)",
      "applies_because": "Overall confidence in this comparison is low and the key factor behind it is not yet evidence backed."
    },
    {
      "question": "Who will argue that Engineering Capacity matters less than Vendor Price Path in this comparison?",
      "principle": "Structured dissent",
      "applies_because": "A critique flagged Engineering Capacity as asserted rather than evidenced, so surfacing dissent tests that assumption directly."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Six months in, the rebuild failed because Engineering Capacity fell short of what the Total Cost of Ownership estimate assumed, and costs overran the vendor alternative.",
    "warning_signs": [
      "Engineering team repeatedly reprioritised away from the billing rebuild",
      "Total Cost of Ownership estimates drifting upward as work proceeds"
    ],
    "mitigation": "Validate engineering capacity with a staffing review before committing to the rebuild timeline.",
    "grounded_in": [
      "edge_capacity_tco",
      "fac_eng_capacity"
    ],
    "review_trigger": "Reconvene if the capacity audit falls short of what the rebuild plan assumes."
  }
}
